// Package v1alpha1 contains API Schema definitions for the isovalent.com v1alpha1 API group.
// +kubebuilder:object:generate=true
// +groupName=isovalent.com
package v1alpha1

import (
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	runtime "k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/runtime/schema"
)

var (
	// GroupVersion is group version used to register these objects.
	GroupVersion = schema.GroupVersion{Group: "isovalent.com", Version: "v1alpha1"}
)

var (
	SchemeBuilder      runtime.SchemeBuilder
	localSchemeBuilder = &SchemeBuilder
	AddToScheme        = localSchemeBuilder.AddToScheme
)

func init() {
	// We only register manually written functions here. The registration of the
	// generated functions takes place in the generated files. The separation
	// makes the code compile even when the generated files are missing.
	localSchemeBuilder.Register(addKnownTypes)
}

// Adds the list of known types to api.Scheme.
func addKnownTypes(scheme *runtime.Scheme) error {
	scheme.AddKnownTypes(GroupVersion,
		&SmartSwitch{}, &SmartSwitchList{},
		&SmartSwitchNetworkPolicy{}, &SmartSwitchNetworkPolicyList{},
		&TetragonNode{}, &TetragonNodeList{},
	)
	metav1.AddToGroupVersion(scheme, GroupVersion)
	return nil
}
